div.script:
document.addEventListener('DOMContentLoaded', function() {
    const wrapper = document.getElementById('cart-main-wrapper');
    if (!wrapper) return;

    function postCartData(url, params) {
        const csrfInput = document.querySelector('input[name="csrf_token"]');
        const csrfToken = csrfInput ? csrfInput.value : '';
        const formData = new FormData();
        formData.append('csrf_token', csrfToken);
        for (const [key, value] of Object.entries(params)) {
            formData.append(key, value);
        }
        return fetch(url, {
            method: 'POST',
            body: formData
        }).then(r => r.json());
    }

    function updateTotals(data) {
        const totalQtyEl = document.getElementById('cart-summary-total-qty');
        const totalPriceEl = document.getElementById('cart-summary-total-price');
        const topbarBadgeEl = document.getElementById('cart-badge');
        const cartTitleEl = document.querySelector('.lg\\:col-span-8 h2');

        if (totalQtyEl) totalQtyEl.innerText = data.total_qty;
        if (totalPriceEl) {
            totalPriceEl.innerText = data.total_price_formatted;
        }

        if (topbarBadgeEl) {
            if (data.total_qty > 0) {
                topbarBadgeEl.innerText = data.total_qty;
                topbarBadgeEl.classList.remove('hidden');
            } else {
                topbarBadgeEl.classList.add('hidden');
            }
        }

        if (cartTitleEl) {
            const count = document.querySelectorAll('.js_cart_item_row').length;
            cartTitleEl.innerText = 'Giỏ Báo Giá (' + count + ')';
        }

        if (data.cart_empty) {
            showEmptyCartState();
        }
    }

    function showEmptyCartState() {
        const itemsList = document.getElementById('cart-items-container');
        if (itemsList) {
            itemsList.innerHTML = `
                <div class="p-space-lg text-center text-on-surface-variant bg-surface-variant rounded-lg mt-4 mb-4">
                    <span class="material-symbols-outlined text-[48px] mb-2 opacity-50">shopping_cart</span>
                    <p>Giỏ báo giá của bạn đang trống.</p>
                </div>
            `;
        }
        const rightCard = document.querySelector('.lg\\:col-span-4');
        if (rightCard) {
            const form = rightCard.querySelector('form');
            if (form) form.remove();

            const priceEl = document.getElementById('cart-summary-total-price');
            if (priceEl) priceEl.innerText = 'Liên hệ Sales';
            const qtyEl = document.getElementById('cart-summary-total-qty');
            if (qtyEl) qtyEl.innerText = '0';
        }
    }

    wrapper.addEventListener('click', function(e) {
        const removeBtn = e.target.closest('.js_remove_cart_item');
        if (removeBtn) {
            e.preventDefault();
            const productId = removeBtn.getAttribute('data-product-id');
            const row = document.getElementById('cart-item-' + productId);
            if (row) {
                row.style.opacity = '0.5';
                row.style.pointerEvents = 'none';
            }

            postCartData('/shop/cart/remove_json', { product_id: productId })
                .then(data => {
                    if (data.success) {
                        if (row) row.remove();
                        updateTotals(data);
                    } else {
                        if (row) {
                            row.style.opacity = '1';
                            row.style.pointerEvents = 'auto';
                        }
                        alert('Lỗi: ' + (data.error || 'Không thể xóa sản phẩm'));
                    }
                })
                .catch(err => {
                    if (row) {
                        row.style.opacity = '1';
                        row.style.pointerEvents = 'auto';
                    }
                    console.error(err);
                });
        }

        const minusBtn = e.target.closest('.js_qty_btn_minus');
        if (minusBtn) {
            e.preventDefault();
            const productId = minusBtn.getAttribute('data-product-id');
            const input = minusBtn.nextElementSibling;
            let val = parseInt(input.value);
            if (val > 1) {
                input.value = val - 1;
                triggerQtyUpdate(productId, val - 1, input);
            }
        }

        const plusBtn = e.target.closest('.js_qty_btn_plus');
        if (plusBtn) {
            e.preventDefault();
            const productId = plusBtn.getAttribute('data-product-id');
            const input = plusBtn.previousElementSibling;
            let val = parseInt(input.value);
            input.value = val + 1;
            triggerQtyUpdate(productId, val + 1, input);
        }
    });

    const clearBtn = document.getElementById('js_clear_cart_btn');
    if (clearBtn) {
        clearBtn.addEventListener('click', function(e) {
            e.preventDefault();
            if (confirm('Bạn có chắc chắn muốn làm trống giỏ hàng?')) {
                postCartData('/shop/cart/clear_json', {})
                    .then(data => {
                        if (data.success) {
                            const rows = document.querySelectorAll('.js_cart_item_row');
                            rows.forEach(r => r.remove());
                            updateTotals(data);
                        }
                    })
                    .catch(console.error);
            }
        });
    }

    wrapper.addEventListener('change', function(e) {
        const input = e.target.closest('.js_qty_input');
        if (input) {
            const productId = input.getAttribute('data-product-id');
            let val = parseInt(input.value);
            if (isNaN(val) || val < 1) {
                val = 1;
                input.value = 1;
            }
            triggerQtyUpdate(productId, val, input);
        }
    });

    function triggerQtyUpdate(productId, qty, inputEl) {
        const form = inputEl.closest('form');
        if (form) form.style.opacity = '0.7';

        postCartData('/shop/cart/update_json', { product_id: productId, qty: qty })
            .then(data => {
                if (form) form.style.opacity = '1';
                if (data.success) {
                    updateTotals(data);
                } else {
                    alert('Lỗi: ' + (data.error || 'Không thể cập nhật số lượng'));
                }
            })
            .catch(err => {
                if (form) form.style.opacity = '1';
                console.error(err);
            });
    }
});
